# ----- INNER JOIN -----

def _parse_join(
    self, left_table: str, items: List[SelectItem]
) -> Tuple[str, JoinOn]:
    """Parse ``[INNER] JOIN right ON left.a = right.b`` after FROM.

    Only exactly one INNER JOIN is supported: no aliases, no LEFT/RIGHT
    joins, no second JOIN, and ON must be one equality of one column from
    each table.
    """
    first = self._next()
    if first.kind is _TokKind.KEYWORD and first.text == "INNER":
        self._expect_keyword("JOIN")
    elif not (first.kind is _TokKind.KEYWORD and first.text == "JOIN"):
        raise ValueError("expected INNER JOIN after the FROM table")
    right_tok = self._next()
    if right_tok.kind is not _TokKind.IDENT:
        raise ValueError("joined table name must be a simple identifier")
    if right_tok.text == left_table:
        raise ValueError(
            f"join tables must have distinct names: {left_table!r} and "
            f"{right_tok.text!r} are the same table"
        )
    self._expect_keyword("ON")
    first_ref = self._parse_column_ref(require_qualified=True)
    op_tok = self._expect(_TokKind.OP)
    if op_tok.text != "=":
        raise ValueError("ON must be a single column equality using '='")
    second_ref = self._parse_column_ref(require_qualified=True)
    tok = self._peek()
    if tok.kind is _TokKind.KEYWORD and tok.text in (
        "AND", "OR", "INNER", "JOIN", "ON",
    ):
        raise ValueError(
            "ON must be exactly one cross-table column equality, with no "
            "combined conditions or further joins"
        )
    # The two sides must belong to different tables, one to each.
    tables = {first_ref.table, second_ref.table}
    if first_ref.table == second_ref.table:
        raise ValueError(
            "ON must compare one column from each table, not two columns "
            "of the same table"
        )
    if tables != {left_table, right_tok.text}:
        raise ValueError(
            "ON columns must be qualified by the two joined table names"
        )
    if first_ref.table == left_table:
        left_ref, right_ref = first_ref, second_ref
    else:
        left_ref, right_ref = second_ref, first_ref
    for item in items:
        if item.table is not None and item.table not in tables:
            raise ValueError(
                f"unknown table qualifier {item.table!r} in SELECT item "
                f"{item.text!r}"
            )
    return right_tok.text, JoinOn(left_ref, right_ref)

def _parse_column_ref(self, require_qualified: bool = False) -> ColumnRef:
    """Parse ``identifier`` or ``identifier . identifier``."""
    first = self._expect(_TokKind.IDENT)
    if self._peek().kind is _TokKind.DOT:
        self._next()
        second = self._expect(_TokKind.IDENT)
        return ColumnRef(second.text, first.text, f"{first.text}.{second.text}")
    if require_qualified:
        raise ValueError(
            "ON columns must be qualified as table.column"
        )
    return ColumnRef(first.text)

def _validate_join(self, items: List[SelectItem]) -> None:
    """A join query is a plain projection: no aggregates at all."""
    for item in items:
        if item.kind != "column":
            raise ValueError(
                "aggregate SELECT expressions are not supported in a "
                "join query"
            )

